DROP TABLE IF EXISTS `proceso_externos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `proceso_externos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `orden_produccion_id` bigint unsigned NOT NULL,
  `material_origen_id` bigint unsigned NOT NULL,
  `proveedor_destino_id` bigint unsigned NOT NULL,
  `etapa_componente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cantidad_salida` decimal(12,4) DEFAULT NULL,
  `unidad_medida` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bodega_origen` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `servicio_proceso` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_salida` datetime NOT NULL,
  `fecha_prevista_regreso` date DEFAULT NULL,
  `resultado_observaciones` text COLLATE utf8mb4_unicode_ci,
  `fecha_regreso_real` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `proceso_externos_orden_produccion_id_foreign` (`orden_produccion_id`),
  KEY `proceso_externos_material_origen_id_foreign` (`material_origen_id`),
  KEY `proceso_externos_proveedor_destino_id_foreign` (`proveedor_destino_id`),
  CONSTRAINT `proceso_externos_material_origen_id_foreign` FOREIGN KEY (`material_origen_id`) REFERENCES `materials` (`id`),
  CONSTRAINT `proceso_externos_orden_produccion_id_foreign` FOREIGN KEY (`orden_produccion_id`) REFERENCES `orden_produccions` (`id`),
  CONSTRAINT `proceso_externos_proveedor_destino_id_foreign` FOREIGN KEY (`proveedor_destino_id`) REFERENCES `proveedors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
